local vmem=emu.memType.snesVideoRam;local rommem=emu.memType.snesPrgRom
local originalControllerPlayer=0
local displayPass=0;local numberMode=''
local function verify(index)
 for _,c in ipairs(expected[index]) do
  local cell,tile,source=c[1],c[2],c[3]
  assert((emu.read(cell*2,vmem)&255)==tile,'upper map')
  assert((emu.read((cell+32)*2,vmem)&255)==tile+1,'lower map')
  for i=0,31 do assert((emu.read(0xC000+tile*16+i,vmem)&255)==(emu.read(source+i,rommem)&255),'12px bitmap') end
 end
end
emu.addEventCallback(function()
 if n==300 or n==900 then
  assert(rendered>0,'native STATUS entry did not run')
  for i=1,15 do verify(i) end
  local q=tonumber(os.getenv('UI_PLAYER'));local cond=r(0x1EB+q)
  verify(16+q);verify(18+cond)
  for row=0,2 do verify(21+row*111+r(0x1E5+row*2+q)) end
  local addresses={0x78ED,0x792C,0x796C,0x79A8,0x78FB,0x793B,0x797B,0x79BB,0x79FB,0x7A3B,0x7A7B}
  local high={'99','255','255','9999999','255','255','255','255','255','127','255'}
  local low={'01','001','001','0000000','001','001','001','001','001','000','001'}
  for i,cell in ipairs(addresses) do
   local want=(numberMode=='high' and high or low)[i]
   local actual=''
   for k=0,#want-1 do
    local tile=emu.read((cell+k)*2,vmem)&255
    assert(tile>=0x10 and tile<=0x19,'numeric tile corrupted')
    actual=actual..tostring(tile-0x10)
   end
   assert(actual==want,'native number changed '..i..': '..actual..'/'..want)
  end
  p('NATIVE_NUMBERS_VERIFIED '..numberMode)
  checked=true;p('STATUS12_PIXELS_VERIFIED all labels/name/condition/equipment')
  if n==900 then assert(rendered>=2,'STATUS did not reopen');p('STATUS_REOPEN_VERIFIED redraws='..rendered) end
 end
 if n>=maxf then assert(checked,'STATUS12 not checked') end
end,emu.eventType.endFrame)

emu.addMemoryCallback(function()
 local mode=os.getenv('UI_NUMBERS')
 local q=tonumber(os.getenv('UI_PLAYER') or '0')
 displayPass=displayPass+1
 originalControllerPlayer=r(0x1BA6)
 emu.write(0x1BA6,q,mem)
 if displayPass>1 then
  mode=mode=='high' and 'low' or 'high'
  emu.write(0x1EB+q,(tonumber(os.getenv('UI_CONDITION'))+1)%3,mem)
  local ids=os.getenv('UI_EQUIPMENT')=='long' and {0,0,0} or {64,73,110}
  for j,id in ipairs(ids) do emu.write(0x1E5+(j-1)*2+q,id,mem) end
  p('CONTROLLED_CHANGE condition/equipment/numbers between real menu openings')
 end
 numberMode=mode
 if mode=='low' or mode=='high' then
  local high=mode=='high'
  for _,address in ipairs({0x102,0x104,0x106,0x10E,0x110,0x112,0x114,0x11A}) do
   local value=high and (address==0x102 and 99 or 255) or 1
   emu.write(address+q,value,mem)
  end
  for _,address in ipairs({0x1F2,0x1F4,0x1F6}) do emu.write(address+q,0,mem) end
  local xp=high and 9999999 or 0
  for i=0,2 do emu.write(0x108+q*3+i,(xp>>(8*i))&255,mem) end
  p('CONTROLLED_NATIVE_NUMBERS '..mode..'; original FA8B renderer')
 end
